user_prompt_template:
Generate a comprehensive trading brief for {asset}.

Market Data:
- Current Price: {current_price}
- Support Levels: {support_levels}
- Resistance Levels: {resistance_levels}

Technical Analysis (Multi-Timeframe):
{macro_features}

Fundamental Context:
- News Summary: {news_summary}
- Economic Summary: {econ_summary}

Anomaly Signals (if any):
{anomaly_signals}

Provide output in this exact JSON structure:
{
  "asset": "{asset}",
  "time_focus": ["15m", "1h", "4h", "1d"],
  "key_levels": {
    "support": [float, float, ...],
    "resistance": [float, float, ...]
  },
  "market_state": {
    "regime": "trend|range|transition",
    "drivers": ["driver1", "driver2", ...]
  },
  "futures_plan": {
    "bias": "long|short|neutral",
    "long_zone": [low, high],
    "short_zone": [low, high],
    "invalid_level": float,
    "take_profit": [tp1, tp2, tp3],
    "risk_control": "risk management explanation"
  },
  "spot_plan": {
    "bias": "buy_dip|breakout_follow|wait",
    "buy_zone": [low, high],
    "sell_zone": [low, high],
    "take_profit": [tp1, tp2],
    "risk_control": "risk management explanation"
  },
  "one_sentence_summary": "concise market summary",
  "disclaimer": "仅供参考，不构成投资建议"
}
